const data=window.CASES;data.forEach((c,i)=>{const h=window.HIGHLIGHTS[i];c.metric=h[0];c.metricLabel=h[1];c.guide=window.GUIDES[i];});let platform='全部平台',category='全部问题',query='',page=1,pageSize=10,totalPages=1;const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const platformNames=['全部平台',...Object.entries(data.reduce((counts,c)=>(counts[c.platform]=(counts[c.platform]||0)+1,counts),{})).sort((a,b)=>b[1]-a[1]).map(([p])=>p)];const platformLogos={"小红书":"logos/xiaohongshu.ico","抖音":"logos/douyin.ico","闲鱼":"logos/goofish.png","微信公众号":"logos/weixin-mp.png","微信小程序":"logos/weixin-mini.png","微信视频号":"logos/weixin-channels.png","微信私域":"logos/weixin.png","企业微信":"logos/wecom.png","YouTube":"logos/youtube.ico","B站":"logos/bilibili.png","X":"logos/x.png","TikTok":"logos/tiktok.png","Google 搜索":"logos/google.ico","淘宝":"logos/taobao.png","TEMU":"logos/temu.ico","飞书":"logos/feishu.ico","独立站":"logos/website.svg","快手":"logos/channel.svg","通用工具":"logos/website.svg","全部平台":"logos/all.svg"};const categories=['全部问题','账号与申诉','流量与涨粉','成交与转化','效率与自动化','开发与支付','开发与交付','供应链与协作'];

function renderTailInvite(question='从别人的实战经历里，寻找自己的下一步。'){
return `<section class="tail-invite" aria-label="免费领取生财有术体验卡"><div class="tail-brand"><img src="invite-brand.png" alt="生财有术：用好AI，跟上时代" width="322" height="372" loading="lazy"></div><div class="tail-action"><span class="tail-kicker">看过案例，继续寻找答案</span><h3>把这份启发，变成你的下一步</h3><p>${esc(question)}</p><p class="tail-benefits"><strong class="free-emphasis">免费</strong>体验三天寻找答案，立即开启你的副业之旅</p><a class="tail-qr" href="invite-qr.png" target="_blank" rel="noopener" aria-label="打开体验卡二维码大图"><img src="invite-qr.png" alt="邀请您加入生财有术，扫码免费领取体验卡" width="325" height="175" loading="lazy"></a><a class="tail-button" href="invite-qr.png" target="_blank" rel="noopener">打开二维码，领取体验卡 <span aria-hidden="true">↗</span></a><p class="tail-help">电脑：微信扫码 · 手机：点开图片，长按保存后识别二维码</p><small>可体验的内容以领取后的实际权限为准</small></div></section>`;
}

function renderControls(){$('#platforms').innerHTML=platformNames.map((p,i)=>`<button data-platform="${p}" class="${p===platform?'active':''}" aria-pressed="${p===platform}"><span class="platform-icon" aria-hidden="true"><img src="${platformLogos[p]}" alt="" width="22" height="22"></span>${p}<span class="platform-count">${p==='全部平台'?data.length:data.filter(c=>c.platform===p).length}</span></button>`).join('');$('#categories').innerHTML=categories.map(c=>`<button data-category="${c}" class="${c===category?'active':''}" aria-pressed="${c===category}">${c}</button>`).join('');}
function render(){renderControls();const words=query.trim().toLowerCase().split(/\s+/).filter(Boolean);const cases=data.filter(c=>(platform==='全部平台'||c.platform===platform)&&(category==='全部问题'||c.category===category)&&words.every(w=>[c.title,c.platform,c.project,c.author,c.category,c.action,c.result,c.sourceTitle,c.platform==='微信公众号'?'限流': '',c.platform==='X'?'Twitter':''].join(' ').toLowerCase().includes(w)));totalPages=Math.max(1,Math.ceil(cases.length/pageSize));page=Math.min(Math.max(1,page),totalPages);const visible=cases.slice((page-1)*pageSize,page*pageSize);$('#result-title').innerHTML=`${esc(platform==='全部平台'?'全部案例':platform)} <span>${cases.length}</span>`;$('#reset').hidden=platform==='全部平台'&&category==='全部问题'&&!query;$('#list').innerHTML=cases.length?visible.map(c=>`<article class="case"><span class="row-number">${String(c.id).padStart(2,'0')}</span><div class="row-copy"><h3><button class="title-button" data-open="${c.id}">${esc(c.title)}</button></h3><div class="case-meta"><span class="platform-tag">${c.platform}</span><span>${c.category}</span><span>2026</span></div></div><div class="row-metric"><strong>${esc(c.metric)}</strong><span>${esc(c.metricLabel)}</span><small>作者自述</small></div><button class="read" data-open="${c.id}">查看解法</button></article>` ).join(''):'<div class="empty"><h3>暂时没有匹配的案例</h3><p>试试更短的关键词，或取消平台、问题类型限制。</p><button data-reset>查看全部案例</button></div>';$('#list').insertAdjacentHTML('beforeend',renderTailInvite()+renderPagination(cases.length));}
function reset(){page=1;platform='全部平台';category='全部问题';query='';$('#search').value='';render();}
function openCase(id){const c=data.find(c=>c.id===Number(id));if(!c)return;const related=data.filter(x=>x.id!==c.id&&(x.category===c.category||x.platform===c.platform)).sort((a,b)=>Number(b.category===c.category)-Number(a.category===c.category)).slice(0,3);$('#detail-body').innerHTML=`<div class="case-meta"><span class="platform-tag">${c.platform}</span><span>${c.category} · ${esc(c.sourceDate)} 发帖</span></div><h2 id="detail-title">${esc(c.title)}</h2><div class="hero-result"><span>作者自述的关键结果</span><strong>${esc(c.metric)}</strong><p>${esc(c.metricLabel)}</p></div><section class="detail-section"><h3>当时卡在哪里？</h3><p>${esc(c.guide[0])}</p></section><section class="detail-section"><h3>关键转折是什么？</h3><p>${esc(c.guide[1])}</p></section><section class="detail-section reader-fit"><h3>适合谁参考？</h3><p>${esc(c.guide[2])}</p></section><p class="note">${esc(c.note)}</p><p class="note">结果为作者或当事人自述，未独立核验。历史经验同样保留。</p><a class="source-link" href="${c.url}" target="_blank" rel="noopener noreferrer"><span>领取后查找原帖 · 以实际阅读权限为准</span>${esc(c.sourceTitle)} ↗</a>${related.length?`<div class="related"><h3>相似问题，其他解法</h3>${related.map(x=>`<button data-open="${x.id}">${x.platform} · ${esc(x.title)} ↗</button>`).join('')}</div>`:''}${renderTailInvite(c.guide[3])}`;if(!$('#detail').open)$('#detail').showModal();$('#detail').scrollTop=0;}
document.addEventListener('click',e=>{const p=e.target.closest('[data-platform]'),c=e.target.closest('[data-category]'),o=e.target.closest('[data-open]');if(p){const pos=$('#platforms').scrollLeft;platform=p.dataset.platform;page=1;render();$('#platforms').scrollLeft=pos;}if(c){category=c.dataset.category;page=1;render();}if(o)openCase(o.dataset.open);if(e.target.closest('[data-reset]'))reset();});$('#search').addEventListener('input',e=>{query=e.target.value;page=1;render();});$('#reset').onclick=reset;$('#close').onclick=()=>$('#detail').close();$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)&&!$('#detail').open){e.preventDefault();$('#search').focus();}});render();

function renderPagination(total){
 if(!total)return '';
 const pages=[...new Set([1,page-1,page,page+1,totalPages])].filter(n=>n>=1&&n<=totalPages).sort((a,b)=>a-b);
 let previous=0;const links=pages.map(n=>{const gap=previous&&n-previous>1?'<span class="page-gap" aria-hidden="true">…</span>':'';previous=n;return gap+'<button type="button" data-page="'+n+'" '+(n===page?'aria-current="page"':'')+' aria-label="第 '+n+' 页">'+n+'</button>';}).join('');
 return '<nav class="pagination" aria-label="案例分页"><div class="page-summary">第 '+((page-1)*pageSize+1)+'–'+Math.min(page*pageSize,total)+' 条，共 '+total+' 条</div><label class="page-size">每页 <select id="page-size" aria-label="每页案例数量">'+[10,30,50].map(n=>'<option value="'+n+'" '+(n===pageSize?'selected':'')+'>'+n+' 条</option>').join('')+'</select></label><div class="page-links"><button type="button" data-page="'+(page-1)+'" '+(page===1?'disabled':'')+'>上一页</button>'+links+'<button type="button" data-page="'+(page+1)+'" '+(page===totalPages?'disabled':'')+'>下一页</button></div></nav>';
}
function goToPage(n){page=Math.min(totalPages,Math.max(1,n));render();const heading=$('#result-title');heading.setAttribute('tabindex','-1');heading.focus({preventScroll:true});heading.scrollIntoView({block:'start',behavior:'auto'});}
document.addEventListener('click',e=>{const button=e.target.closest('[data-page]');if(button&&!button.disabled)goToPage(Number(button.dataset.page));});
document.addEventListener('change',e=>{if(e.target.id==='page-size'){const n=Number(e.target.value);if([10,30,50].includes(n)){pageSize=n;goToPage(1);}}});
